import{_ as t,o,c as d,a2 as a}from"./chunks/framework.C3fpVp7C.js";const u=JSON.parse('{"title":"REST API reference","description":"","frontmatter":{},"headers":[],"relativePath":"reference/api.md","filePath":"reference/api.md","lastUpdated":1792160181000}'),r={name:"reference/api.md"};function i(n,e,s,c,l,p){return o(),d("div",null,[...e[0]||(e[0]=[a('<h1 id="rest-api-reference" tabindex="-1">REST API reference <a class="header-anchor" href="#rest-api-reference" aria-label="Permalink to &quot;REST API reference&quot;">​</a></h1><p>Principal endpoints (grants, approvals, audit, revoking by id) require the admin token as <code>Authorization: Bearer &lt;admin token&gt;</code>. Agent endpoints take the agent token in the request body, so a tool server can forward it without extra headers.</p><p>The full OpenAPI 3.1 description is <code>openapi.yaml</code>, which ships in the npm package. A test keeps it in sync with the routes the server exposes.</p><table tabindex="0"><thead><tr><th>Method and path</th><th>Auth</th><th>Purpose</th></tr></thead><tbody><tr><td><code>GET /healthz</code></td><td>none</td><td>Liveness check</td></tr><tr><td><code>GET /.well-known/jwks.json</code></td><td>none</td><td>Public signing keys</td></tr><tr><td><code>POST /v1/grants</code></td><td>admin</td><td>Create a grant</td></tr><tr><td><code>GET /v1/grants</code></td><td>admin</td><td>List grants</td></tr><tr><td><code>GET /v1/grants/{id}</code></td><td>admin</td><td>Get a grant and its tokens</td></tr><tr><td><code>POST /v1/grants/{id}/revoke</code></td><td>admin</td><td>Revoke a grant</td></tr><tr><td><code>POST /v1/tokens/attenuate</code></td><td>token</td><td>Derive a narrower token</td></tr><tr><td><code>POST /v1/tokens/introspect</code></td><td>token</td><td>Report whether a token is active</td></tr><tr><td><code>POST /v1/tokens/revoke</code></td><td>token or admin</td><td>Revoke a token and its descendants</td></tr><tr><td><code>POST /v1/check</code></td><td>token</td><td>Decide whether a token permits a request</td></tr><tr><td><code>GET /v1/approvals</code></td><td>admin</td><td>List approval requests</td></tr><tr><td><code>POST /v1/approvals/{id}/approve</code></td><td>admin</td><td>Approve a pending request</td></tr><tr><td><code>POST /v1/approvals/{id}/deny</code></td><td>admin</td><td>Deny a pending request</td></tr><tr><td><code>GET /v1/audit</code></td><td>admin</td><td>Read audit entries</td></tr><tr><td><code>GET /v1/audit/verify</code></td><td>admin</td><td>Verify the audit hash chain on the server</td></tr></tbody></table><h2 id="operations" tabindex="-1">Operations <a class="header-anchor" href="#operations" aria-label="Permalink to &quot;Operations&quot;">​</a></h2><h3 id="liveness-check" tabindex="-1">Liveness check <a class="header-anchor" href="#liveness-check" aria-label="Permalink to &quot;Liveness check&quot;">​</a></h3><p><code>GET /healthz</code> (operation <code>health</code>)</p><p>Responses:</p><ul><li><code>200</code>: The server is up.</li></ul><h3 id="public-signing-keys" tabindex="-1">Public signing keys <a class="header-anchor" href="#public-signing-keys" aria-label="Permalink to &quot;Public signing keys&quot;">​</a></h3><p><code>GET /.well-known/jwks.json</code> (operation <code>jwks</code>)</p><p>Use these keys to verify agent tokens offline.</p><p>Responses:</p><ul><li><code>200</code>: A JSON Web Key Set with one Ed25519 key.</li></ul><h3 id="create-a-grant" tabindex="-1">Create a grant <a class="header-anchor" href="#create-a-grant" aria-label="Permalink to &quot;Create a grant&quot;">​</a></h3><p><code>POST /v1/grants</code> (operation <code>createGrant</code>)</p><p>Delegates scopes to an agent and returns the grant with its root token.</p><p>Responses:</p><ul><li><code>201</code>: Grant created.</li><li><code>400</code>: Invalid input (<code>bad_request</code> or <code>invalid_scope</code>).</li><li><code>401</code>: Missing admin token, or an invalid, expired or revoked agent token.</li></ul><h3 id="list-grants" tabindex="-1">List grants <a class="header-anchor" href="#list-grants" aria-label="Permalink to &quot;List grants&quot;">​</a></h3><p><code>GET /v1/grants</code> (operation <code>listGrants</code>)</p><p>Responses:</p><ul><li><code>200</code>: Grants, newest first.</li><li><code>401</code>: Missing admin token, or an invalid, expired or revoked agent token.</li></ul><h3 id="get-a-grant-and-its-tokens" tabindex="-1">Get a grant and its tokens <a class="header-anchor" href="#get-a-grant-and-its-tokens" aria-label="Permalink to &quot;Get a grant and its tokens&quot;">​</a></h3><p><code>GET /v1/grants/{id}</code> (operation <code>getGrant</code>)</p><p>Responses:</p><ul><li><code>200</code>: The grant and every token issued under it.</li><li><code>401</code>: Missing admin token, or an invalid, expired or revoked agent token.</li><li><code>404</code>: No such resource.</li></ul><h3 id="revoke-a-grant" tabindex="-1">Revoke a grant <a class="header-anchor" href="#revoke-a-grant" aria-label="Permalink to &quot;Revoke a grant&quot;">​</a></h3><p><code>POST /v1/grants/{id}/revoke</code> (operation <code>revokeGrant</code>)</p><p>Revokes the grant and every token issued under it.</p><p>Responses:</p><ul><li><code>200</code>: Ids of the tokens that this call revoked.</li><li><code>401</code>: Missing admin token, or an invalid, expired or revoked agent token.</li><li><code>404</code>: No such resource.</li></ul><h3 id="derive-a-narrower-token" tabindex="-1">Derive a narrower token <a class="header-anchor" href="#derive-a-narrower-token" aria-label="Permalink to &quot;Derive a narrower token&quot;">​</a></h3><p><code>POST /v1/tokens/attenuate</code> (operation <code>attenuate</code>)</p><p>Every requested scope must be covered by a single scope of the parent token. The child expires no later than the parent, and its use limit is no higher than the parent&#39;s.</p><p>Responses:</p><ul><li><code>201</code>: Child token issued.</li><li><code>400</code>: Invalid input (<code>bad_request</code> or <code>invalid_scope</code>).</li><li><code>401</code>: Missing admin token, or an invalid, expired or revoked agent token.</li><li><code>403</code>: <code>scope_escalation</code> or <code>depth_exceeded</code>.</li></ul><h3 id="report-whether-a-token-is-active" tabindex="-1">Report whether a token is active <a class="header-anchor" href="#report-whether-a-token-is-active" aria-label="Permalink to &quot;Report whether a token is active&quot;">​</a></h3><p><code>POST /v1/tokens/introspect</code> (operation <code>introspect</code>)</p><p>Responses:</p><ul><li><code>200</code>: Token status. Never consumes a use.</li></ul><h3 id="revoke-a-token-and-its-descendants" tabindex="-1">Revoke a token and its descendants <a class="header-anchor" href="#revoke-a-token-and-its-descendants" aria-label="Permalink to &quot;Revoke a token and its descendants&quot;">​</a></h3><p><code>POST /v1/tokens/revoke</code> (operation <code>revokeToken</code>)</p><p>Pass <code>token</code> to revoke the presented token. Pass <code>jti</code> with the admin token to revoke any token by id.</p><p>Responses:</p><ul><li><code>200</code>: Ids of the tokens that this call revoked.</li><li><code>400</code>: Invalid input (<code>bad_request</code> or <code>invalid_scope</code>).</li><li><code>401</code>: Missing admin token, or an invalid, expired or revoked agent token.</li><li><code>404</code>: No such resource.</li></ul><h3 id="decide-whether-a-token-permits-a-request" tabindex="-1">Decide whether a token permits a request <a class="header-anchor" href="#decide-whether-a-token-permits-a-request" aria-label="Permalink to &quot;Decide whether a token permits a request&quot;">​</a></h3><p><code>POST /v1/check</code> (operation <code>check</code>)</p><p>Returns <code>allow</code>, <code>deny</code> or <code>approval_required</code>. An <code>allow</code> consumes one use on every token in the chain unless <code>dryRun</code> is true. Every call is written to the audit log. An invalid, expired or revoked token yields <code>deny</code> with HTTP 200, so tool servers handle one response shape.</p><p>Responses:</p><ul><li><code>200</code>: The decision.</li><li><code>400</code>: Invalid input (<code>bad_request</code> or <code>invalid_scope</code>).</li></ul><h3 id="list-approval-requests" tabindex="-1">List approval requests <a class="header-anchor" href="#list-approval-requests" aria-label="Permalink to &quot;List approval requests&quot;">​</a></h3><p><code>GET /v1/approvals</code> (operation <code>listApprovals</code>)</p><p>Responses:</p><ul><li><code>200</code>: Approvals, oldest first.</li><li><code>400</code>: Invalid input (<code>bad_request</code> or <code>invalid_scope</code>).</li><li><code>401</code>: Missing admin token, or an invalid, expired or revoked agent token.</li></ul><h3 id="approve-a-pending-request" tabindex="-1">Approve a pending request <a class="header-anchor" href="#approve-a-pending-request" aria-label="Permalink to &quot;Approve a pending request&quot;">​</a></h3><p><code>POST /v1/approvals/{id}/approve</code> (operation <code>approve</code>)</p><p>Responses:</p><ul><li><code>200</code>: Updated approval.</li><li><code>404</code>: No such resource.</li><li><code>409</code>: The approval has already been decided.</li></ul><h3 id="deny-a-pending-request" tabindex="-1">Deny a pending request <a class="header-anchor" href="#deny-a-pending-request" aria-label="Permalink to &quot;Deny a pending request&quot;">​</a></h3><p><code>POST /v1/approvals/{id}/deny</code> (operation <code>deny</code>)</p><p>Responses:</p><ul><li><code>200</code>: Updated approval.</li><li><code>404</code>: No such resource.</li><li><code>409</code>: The approval has already been decided.</li></ul><h3 id="read-audit-entries" tabindex="-1">Read audit entries <a class="header-anchor" href="#read-audit-entries" aria-label="Permalink to &quot;Read audit entries&quot;">​</a></h3><p><code>GET /v1/audit</code> (operation <code>listAudit</code>)</p><p>Responses:</p><ul><li><code>200</code>: Entries in sequence order.</li><li><code>400</code>: Invalid input (<code>bad_request</code> or <code>invalid_scope</code>).</li><li><code>401</code>: Missing admin token, or an invalid, expired or revoked agent token.</li></ul><h3 id="verify-the-audit-hash-chain-on-the-server" tabindex="-1">Verify the audit hash chain on the server <a class="header-anchor" href="#verify-the-audit-hash-chain-on-the-server" aria-label="Permalink to &quot;Verify the audit hash chain on the server&quot;">​</a></h3><p><code>GET /v1/audit/verify</code> (operation <code>verifyAudit</code>)</p><p>For an independent check, download the entries with <code>/v1/audit</code> and verify them yourself, for example with <code>agent-auth audit verify</code>.</p><p>Responses:</p><ul><li><code>200</code>: Verification result.</li><li><code>401</code>: Missing admin token, or an invalid, expired or revoked agent token.</li></ul>',72)])])}const v=t(r,[["render",i]]);export{u as __pageData,v as default};
